CREATE TABLE jwks (id TEXT PRIMARY KEY, publicKey TEXT NOT NULL, privateKey TEXT NOT NULL, createdAt INTEGER NOT NULL, expiresAt INTEGER, alg TEXT, crv TEXT);
CREATE TABLE oauthClient (id TEXT PRIMARY KEY, clientId TEXT NOT NULL UNIQUE, clientSecret TEXT, clientDiscoveryId TEXT, disabled INTEGER, skipConsent INTEGER, enableEndSession INTEGER, subjectType TEXT, scopes TEXT, clientCredentialsScopes TEXT, userId TEXT REFERENCES user(id), createdAt INTEGER, updatedAt INTEGER, name TEXT, uri TEXT, icon TEXT, contacts TEXT, tos TEXT, policy TEXT, softwareId TEXT, softwareVersion TEXT, softwareStatement TEXT, redirectUris TEXT NOT NULL, postLogoutRedirectUris TEXT, backchannelLogoutUri TEXT, backchannelLogoutSessionRequired INTEGER, tokenEndpointAuthMethod TEXT, applicationType TEXT, jwks TEXT, jwksUri TEXT, grantTypes TEXT, responseTypes TEXT, requirePKCE INTEGER, dpopBoundAccessTokens INTEGER, referenceId TEXT, metadata TEXT);
CREATE INDEX oauthClient_user ON oauthClient(userId);
CREATE TABLE oauthResource (id TEXT PRIMARY KEY, identifier TEXT NOT NULL UNIQUE, name TEXT NOT NULL, accessTokenTtl INTEGER, refreshTokenTtl INTEGER, signingAlgorithm TEXT, signingKeyId TEXT, allowedScopes TEXT, customClaims TEXT, dpopBoundAccessTokensRequired INTEGER, disabled INTEGER, createdAt INTEGER, updatedAt INTEGER, policyVersion INTEGER, metadata TEXT);
CREATE TABLE oauthClientResource (id TEXT PRIMARY KEY, clientId TEXT NOT NULL REFERENCES oauthClient(clientId) ON DELETE CASCADE, resourceId TEXT NOT NULL REFERENCES oauthResource(identifier) ON DELETE CASCADE, metadata TEXT, createdAt INTEGER);
CREATE INDEX oauthClientResource_client ON oauthClientResource(clientId);
CREATE INDEX oauthClientResource_resource ON oauthClientResource(resourceId);
CREATE TABLE oauthRefreshToken (id TEXT PRIMARY KEY, token TEXT NOT NULL UNIQUE, clientId TEXT NOT NULL REFERENCES oauthClient(clientId), sessionId TEXT REFERENCES session(id) ON DELETE SET NULL, userId TEXT NOT NULL REFERENCES user(id), referenceId TEXT, authorizationCodeId TEXT, resources TEXT, requestedUserInfoClaims TEXT, expiresAt INTEGER, createdAt INTEGER, revoked INTEGER, rotatedAt INTEGER, rotationReplayResponse TEXT, rotationReplayExpiresAt INTEGER, authTime INTEGER, confirmation TEXT, scopes TEXT NOT NULL);
CREATE INDEX oauthRefreshToken_client ON oauthRefreshToken(clientId);
CREATE INDEX oauthRefreshToken_session ON oauthRefreshToken(sessionId);
CREATE INDEX oauthRefreshToken_user ON oauthRefreshToken(userId);
CREATE INDEX oauthRefreshToken_code ON oauthRefreshToken(authorizationCodeId);
CREATE TABLE oauthAccessToken (id TEXT PRIMARY KEY, token TEXT UNIQUE, clientId TEXT NOT NULL REFERENCES oauthClient(clientId), sessionId TEXT REFERENCES session(id) ON DELETE SET NULL, userId TEXT REFERENCES user(id), referenceId TEXT, authorizationCodeId TEXT, resources TEXT, requestedUserInfoClaims TEXT, refreshId TEXT REFERENCES oauthRefreshToken(id), expiresAt INTEGER, createdAt INTEGER, revoked INTEGER, confirmation TEXT, scopes TEXT NOT NULL);
CREATE INDEX oauthAccessToken_client ON oauthAccessToken(clientId);
CREATE INDEX oauthAccessToken_session ON oauthAccessToken(sessionId);
CREATE INDEX oauthAccessToken_user ON oauthAccessToken(userId);
CREATE INDEX oauthAccessToken_code ON oauthAccessToken(authorizationCodeId);
CREATE INDEX oauthAccessToken_refresh ON oauthAccessToken(refreshId);
CREATE TABLE oauthConsent (id TEXT PRIMARY KEY, clientId TEXT NOT NULL REFERENCES oauthClient(clientId), userId TEXT REFERENCES user(id), referenceId TEXT, resources TEXT, requestedUserInfoClaims TEXT, scopes TEXT NOT NULL, createdAt INTEGER, updatedAt INTEGER);
CREATE INDEX oauthConsent_client ON oauthConsent(clientId);
CREATE INDEX oauthConsent_user ON oauthConsent(userId);
CREATE TABLE oauthClientAssertion (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL);
